import math
import statistics

import pytest

def annualised_vol(returns):
    if len(returns) < 2:
        raise ValueError("need at least two returns")
    return statistics.stdev(returns) * math.sqrt(252)

@pytest.mark.parametrize("returns", [[], [0.01]])
def test_too_few_returns_raise(returns):
    with pytest.raises(ValueError, match="two returns"):
        annualised_vol(returns)

def test_equal_returns_have_zero_vol():
    assert annualised_vol([0.004, 0.004, 0.004]) == pytest.approx(0.0)

def test_vol_by_hand():
    assert annualised_vol([0.01, -0.01]) == pytest.approx(math.sqrt(0.0002 * 252))

